from functools import lru_cache
from typing import List

def get_probability(scores: List[List[int]], prob: List[List[int]], n: int, x: int) -> float:
    # scores[i], prob[i] in percent for mix i
    mixes = []
    for i in range(len(scores)):
        # convert to (score, p) including p_fail = 1 - sum
        psum = sum(prob[i]) / 100.0
        m = [(s, p / 100.0) for s, p in zip(scores[i], prob[i])]
        m.append((0, max(0.0, 1 - psum)))  # failure
        mixes.append(m)

    @lru_cache(maxsize=None)
    def f(k, s):
        if s == 0: return 1.0
        if s < 0 or k == 0: return 0.0
        best = 0.0
        for mix in mixes:
            ev = 0.0
            for sc, p in mix:
                ev += p * f(k - 1, s - sc)
            if ev > best: best = ev
        return best

    return round(f(n, x), 3)

import java.util.*;

class Solution {
    double[][] memo;
    int n, x;
    List<List<double[]>> mixes;
    public double getProbability(int[][] scores, int[][] prob, int n, int x) {
        this.n = n; this.x = x;
        mixes = new ArrayList<>();
        for (int i = 0; i < scores.length; i++) {
            List<double[]> m = new ArrayList<>();
            double psum = 0;
            for (int j = 0; j < scores[i].length; j++) { m.add(new double[]{scores[i][j], prob[i][j] / 100.0}); psum += prob[i][j] / 100.0; }
            m.add(new double[]{0, Math.max(0, 1 - psum)});
            mixes.add(m);
        }
        memo = new double[n + 1][x + 1];
        for (double[] row : memo) Arrays.fill(row, -1);
        return Math.round(f(n, x) * 1000) / 1000.0;
    }
    double f(int k, int s) {
        if (s == 0) return 1.0;
        if (s < 0 || k == 0) return 0.0;
        if (memo[k][s] >= 0) return memo[k][s];
        double best = 0;
        for (var mix : mixes) {
            double ev = 0;
            for (double[] sp : mix) ev += sp[1] * f(k - 1, (int) (s - sp[0]));
            best = Math.max(best, ev);
        }
        return memo[k][s] = best;
    }
}

#include <bits/stdc++.h>
using namespace std;

class Solution {
    vector<vector<double>> memo;
    int N, X;
    vector<vector<pair<int, double>>> mixes;
    double f(int k, int s) {
        if (s == 0) return 1.0;
        if (s < 0 || k == 0) return 0.0;
        double& v = memo[k][s];
        if (v >= 0) return v;
        double best = 0;
        for (auto& mix : mixes) {
            double ev = 0;
            for (auto& [sc, p] : mix) ev += p * f(k - 1, s - sc);
            best = max(best, ev);
        }
        return v = best;
    }
public:
    double getProbability(vector<vector<int>>& scores, vector<vector<int>>& prob, int n, int x) {
        N = n; X = x;
        for (int i = 0; i < (int)scores.size(); i++) {
            vector<pair<int, double>> m;
            double psum = 0;
            for (int j = 0; j < (int)scores[i].size(); j++) { m.push_back({scores[i][j], prob[i][j] / 100.0}); psum += prob[i][j] / 100.0; }
            m.push_back({0, max(0.0, 1 - psum)});
            mixes.push_back(m);
        }
        memo.assign(n + 1, vector<double>(x + 1, -1));
        return round(f(n, x) * 1000) / 1000.0;
    }
};
